//! Section families of profile definitions beyond the first-scope rectangle (A07.1).
//!
//! A [`SectionShape`] is either a closed-enumeration parametric family ([`SectionFamily`]) with
//! its dimensions in millimetres, or a [`CustomSection`] outline authored point by point. This
//! module only admits the logical values with the F04 section 3 codes and caps and the family's
//! own consistency rules; the outline is generated by the kernel. There is no catalogue and no
//! designation lookup here: a library entry resolves to these values before they reach the model.
//!
//! Every parametric family is placed in the section plane with width along `X` and height along
//! `Y`. Hot-rolled families carry a root (fillet) radius `r`; hollow sections carry the outer
//! corner radius; cold-formed families have one constant thickness `t` and an inner bend radius
//! `r`. A radius of zero is a sharp corner. Family geometry follows public engineering
//! descriptions (EN 10365, ASTM A6, EN 10162); no dimension table is used.

use crate::command::CommandError;
use crate::error::ErrorCode;
use crate::limits::{CONTOUR_POINT_CAP, COORDINATE_CAP_MM, DIMENSION_CAP_MM, MIN_CONTOUR_POINTS};
use beamcraft_geom::tolerance::ABSOLUTE_FLOOR_MM;

/// Largest number of cavities of a custom section (the kernel G05 bound).
pub const MAX_CUSTOM_CAVITIES: usize = 256;
/// Largest total number of points of a custom section (the kernel G05 bound).
pub const MAX_CUSTOM_POINTS: usize = 2048;

/// Closed enumeration of the parametric section families.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum SectionFamily {
    /// Doubly symmetric hot-rolled I or H section: `h, b, tw, tf, r`.
    IShape,
    /// Hot-rolled parallel-flange channel, web on the `-X` side: `h, b, tw, tf, r`.
    Channel,
    /// Hot-rolled angle, legs along `-X` and `-Y` sides: `h, b, t, r`.
    Angle,
    /// Rectangular or square hollow section: `h, b, t, r` (`r` is the outer corner radius).
    Rhs,
    /// Circular hollow section: `d, t`.
    Chs,
    /// Cold-formed C with lips, web on the `-X` side: `h, b, c, t, r`.
    LippedC,
    /// Cold-formed C (U) without lips, web on the `-X` side: `h, b, t, r`.
    PlainC,
    /// Cold-formed Z with lips: `h, b, c, t, r`.
    LippedZ,
    /// Cold-formed hat (omega) section, open side down: `h, b, c, t, r`.
    Omega,
}

impl SectionFamily {
    /// Every family, in token order of this enumeration.
    pub const ALL: [Self; 9] = [
        Self::IShape,
        Self::Channel,
        Self::Angle,
        Self::Rhs,
        Self::Chs,
        Self::LippedC,
        Self::PlainC,
        Self::LippedZ,
        Self::Omega,
    ];

    /// Stable schema token, for example `i_shape`.
    pub const fn token(self) -> &'static str {
        match self {
            Self::IShape => "i_shape",
            Self::Channel => "channel",
            Self::Angle => "angle",
            Self::Rhs => "rhs",
            Self::Chs => "chs",
            Self::LippedC => "lipped_c",
            Self::PlainC => "plain_c",
            Self::LippedZ => "lipped_z",
            Self::Omega => "omega",
        }
    }

    /// The family with this token, or `None`.
    pub fn from_token(token: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|f| f.token() == token)
    }

    /// Parameter names in their stored order, without unit suffix.
    pub const fn parameters(self) -> &'static [&'static str] {
        match self {
            Self::IShape | Self::Channel => &["h", "b", "tw", "tf", "r"],
            Self::Angle | Self::Rhs | Self::PlainC => &["h", "b", "t", "r"],
            Self::Chs => &["d", "t"],
            Self::LippedC | Self::LippedZ | Self::Omega => &["h", "b", "c", "t", "r"],
        }
    }

    /// Whether the family's last parameter is a radius that the simplified representation
    /// drops (every family except the circular hollow section).
    pub const fn has_radius(self) -> bool {
        !matches!(self, Self::Chs)
    }
}

/// An admitted-shape candidate of a parametric family: the family and its values in the order of
/// [`SectionFamily::parameters`].
#[derive(Debug, Clone, PartialEq)]
pub struct ParametricSection {
    family: SectionFamily,
    values: Vec<f64>,
}

fn invalid(field: &'static str, message: &'static str) -> CommandError {
    CommandError::new(ErrorCode::InvalidArgument, field, message)
}

/// Field token of a parameter, for example `tw_mm`.
fn field_of(name: &str) -> &'static str {
    match name {
        "h" => "h_mm",
        "b" => "b_mm",
        "tw" => "tw_mm",
        "tf" => "tf_mm",
        "t" => "t_mm",
        "r" => "r_mm",
        "c" => "c_mm",
        "d" => "d_mm",
        _ => "profile",
    }
}

impl ParametricSection {
    /// Pairs a family with its values. A wrong number of values is `INVALID_ARGUMENT`; the
    /// values themselves are checked by [`Self::validate`].
    pub fn new(family: SectionFamily, values: Vec<f64>) -> Result<Self, CommandError> {
        if values.len() != family.parameters().len() {
            return Err(invalid(
                "profile",
                "wrong number of section parameters for the family",
            ));
        }
        Ok(Self { family, values })
    }

    /// The family.
    pub const fn family(&self) -> SectionFamily {
        self.family
    }

    /// The values in the order of [`SectionFamily::parameters`], in millimetres.
    pub fn values(&self) -> &[f64] {
        &self.values
    }

    /// The same section with its radius set to zero: the outline of the simplified
    /// representation. A family without a radius is returned unchanged.
    pub fn without_radius(&self) -> Self {
        let mut values = self.values.clone();
        if self.family.has_radius()
            && let Some(last) = values.last_mut()
        {
            *last = 0.0;
        }
        Self {
            family: self.family,
            values,
        }
    }

    /// Admits the values in F04 stage order (finiteness, caps, floor) and then the family's
    /// own consistency rules, all as `INVALID_ARGUMENT` naming the parameter.
    pub fn validate(&self) -> Result<(), CommandError> {
        let names = self.family.parameters();
        let named = || names.iter().zip(self.values.iter());
        if let Some((name, _)) = named().find(|(_, v)| !v.is_finite()) {
            return Err(CommandError::new(
                ErrorCode::NonFiniteNumber,
                field_of(name),
                "value is not finite",
            ));
        }
        if let Some((name, _)) = named().find(|(_, v)| v.abs() > DIMENSION_CAP_MM) {
            return Err(CommandError::new(
                ErrorCode::LimitExceeded,
                field_of(name),
                "section dimension exceeds the dimension cap",
            ));
        }
        for (name, value) in named() {
            let radius = *name == "r";
            if radius && *value == 0.0 {
                continue;
            }
            if *value < ABSOLUTE_FLOOR_MM {
                return Err(invalid(
                    field_of(name),
                    if radius {
                        "radius is negative or below the geometric floor"
                    } else {
                        "section dimension is below the geometric floor"
                    },
                ));
            }
        }
        self.consistency()
    }

    fn consistency(&self) -> Result<(), CommandError> {
        let rule = |ok: bool, field: &'static str, message: &'static str| {
            if ok {
                Ok(())
            } else {
                Err(invalid(field, message))
            }
        };
        match (self.family, self.values.as_slice()) {
            (SectionFamily::IShape, &[h, b, tw, tf, r]) => {
                rule(2.0 * tf < h, "tf_mm", "flanges leave no web")?;
                rule(tw < b, "tw_mm", "web is not narrower than the flange")?;
                rule(
                    tw + 2.0 * r <= b,
                    "r_mm",
                    "root radius does not fit the flange",
                )?;
                rule(
                    2.0 * (tf + r) <= h,
                    "r_mm",
                    "root radius does not fit the web",
                )
            }
            (SectionFamily::Channel, &[h, b, tw, tf, r]) => {
                rule(2.0 * tf < h, "tf_mm", "flanges leave no web")?;
                rule(tw < b, "tw_mm", "web is not narrower than the flange")?;
                rule(tw + r <= b, "r_mm", "root radius does not fit the flange")?;
                rule(
                    2.0 * (tf + r) <= h,
                    "r_mm",
                    "root radius does not fit the web",
                )
            }
            (SectionFamily::Angle, &[h, b, t, r]) => {
                rule(t < h && t < b, "t_mm", "thickness is not below both legs")?;
                rule(
                    t + r <= h.min(b),
                    "r_mm",
                    "root radius does not fit the legs",
                )
            }
            (SectionFamily::Rhs, &[h, b, t, r]) => {
                rule(2.0 * t < h.min(b), "t_mm", "walls leave no cavity")?;
                rule(
                    2.0 * r <= h.min(b),
                    "r_mm",
                    "corner radius does not fit the sides",
                )?;
                rule(
                    r <= t || 2.0 * (r - t) < h.min(b) - 2.0 * t,
                    "r_mm",
                    "inner corner radius does not fit the cavity",
                )
            }
            (SectionFamily::Chs, &[d, t]) => rule(2.0 * t < d, "t_mm", "wall leaves no cavity"),
            (SectionFamily::PlainC, &[h, b, t, r]) => {
                let bend = r + t;
                rule(2.0 * bend < h, "r_mm", "bends do not fit the web")?;
                rule(bend < b, "r_mm", "bend does not fit the flange")
            }
            (SectionFamily::LippedC | SectionFamily::LippedZ, &[h, b, c, t, r]) => {
                let bend = r + t;
                rule(2.0 * bend < h, "r_mm", "bends do not fit the web")?;
                rule(2.0 * bend < b, "r_mm", "bends do not fit the flange")?;
                rule(bend < c, "c_mm", "lip is shorter than its bend")?;
                rule(2.0 * c < h, "c_mm", "lips meet or cross")
            }
            (SectionFamily::Omega, &[h, b, c, t, r]) => {
                let bend = r + t;
                rule(2.0 * bend < h, "r_mm", "bends do not fit the webs")?;
                rule(2.0 * bend < b, "r_mm", "bends do not fit the crown")?;
                rule(bend < c, "c_mm", "brim is shorter than its bend")
            }
            _ => Err(invalid(
                "profile",
                "wrong number of section parameters for the family",
            )),
        }
    }
}

/// A user-authored section outline in the section plane, millimetres: one counter-clockwise
/// outer contour and zero or more clockwise cavities. Points are kept exactly as authored; the
/// kernel decides winding, simplicity and containment (F04 P-1).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CustomSection {
    /// Outer contour, counter-clockwise seen from `+Z`.
    pub outer: Vec<[f64; 2]>,
    /// Cavity contours, each clockwise.
    pub cavities: Vec<Vec<[f64; 2]>>,
}

impl CustomSection {
    /// Admits the counts and every coordinate: at least three and at most 1024 points per
    /// contour, at most 256 cavities and 2048 points in total (`LIMIT_EXCEEDED` above,
    /// `INVALID_ARGUMENT` below), finite (`NON_FINITE_NUMBER`) and inside the coordinate cap
    /// (`LIMIT_EXCEEDED`).
    pub fn validate(&self) -> Result<(), CommandError> {
        if self.cavities.len() > MAX_CUSTOM_CAVITIES {
            return Err(CommandError::new(
                ErrorCode::LimitExceeded,
                "cavities_mm",
                "too many cavities",
            ));
        }
        let total = self
            .cavities
            .iter()
            .fold(self.outer.len(), |n, c| n.saturating_add(c.len()));
        if total > MAX_CUSTOM_POINTS {
            return Err(CommandError::new(
                ErrorCode::LimitExceeded,
                "outer_mm",
                "too many section points",
            ));
        }
        for (contour, field) in core::iter::once((&self.outer, "outer_mm"))
            .chain(self.cavities.iter().map(|c| (c, "cavities_mm")))
        {
            if contour.len() > CONTOUR_POINT_CAP {
                return Err(CommandError::new(
                    ErrorCode::LimitExceeded,
                    field,
                    "too many contour points",
                ));
            }
            if contour.len() < MIN_CONTOUR_POINTS {
                return Err(invalid(field, "contour has fewer than three points"));
            }
            let coordinates = || contour.iter().flat_map(|p| p.iter());
            if coordinates().any(|v| !v.is_finite()) {
                return Err(CommandError::new(
                    ErrorCode::NonFiniteNumber,
                    field,
                    "value is not finite",
                ));
            }
            if coordinates().any(|v| v.abs() > COORDINATE_CAP_MM) {
                return Err(CommandError::new(
                    ErrorCode::LimitExceeded,
                    field,
                    "coordinate exceeds the coordinate cap",
                ));
            }
        }
        Ok(())
    }
}

/// The shape of a profile definition beyond the first-scope rectangle.
#[derive(Debug, Clone, PartialEq)]
pub enum SectionShape {
    /// A parametric family.
    Parametric(ParametricSection),
    /// An authored outline.
    Custom(CustomSection),
}

impl SectionShape {
    /// Stable schema token of the shape: the family token or `custom`.
    pub const fn token(&self) -> &'static str {
        match self {
            Self::Parametric(p) => p.family.token(),
            Self::Custom(_) => "custom",
        }
    }

    /// Admits the shape (see [`ParametricSection::validate`] and [`CustomSection::validate`]).
    pub fn validate(&self) -> Result<(), CommandError> {
        match self {
            Self::Parametric(p) => p.validate(),
            Self::Custom(c) => c.validate(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn check(family: SectionFamily, values: &[f64]) -> Result<(), (ErrorCode, &'static str)> {
        ParametricSection::new(family, values.to_vec())
            .and_then(|s| s.validate())
            .map_err(|e| (e.code, e.field))
    }

    #[test]
    fn tokens_round_trip_and_parameter_counts_are_fixed() {
        for family in SectionFamily::ALL {
            assert_eq!(SectionFamily::from_token(family.token()), Some(family));
            let n = family.parameters().len();
            assert!(ParametricSection::new(family, vec![1.0; n]).is_ok());
            assert_eq!(
                ParametricSection::new(family, vec![1.0; n + 1]).map_err(|e| e.code),
                Err(ErrorCode::InvalidArgument)
            );
        }
        assert_eq!(SectionFamily::from_token("rectangle"), None);
        assert_eq!(SectionFamily::from_token("I_SHAPE"), None);
    }

    #[test]
    fn synthetic_sections_of_every_family_are_admitted() {
        let ok: [(SectionFamily, &[f64]); 9] = [
            (SectionFamily::IShape, &[300.0, 150.0, 7.0, 10.0, 15.0]),
            (SectionFamily::Channel, &[200.0, 80.0, 6.0, 10.0, 10.0]),
            (SectionFamily::Angle, &[100.0, 80.0, 8.0, 10.0]),
            (SectionFamily::Rhs, &[200.0, 100.0, 6.0, 12.0]),
            (SectionFamily::Chs, &[168.0, 5.0]),
            (SectionFamily::LippedC, &[150.0, 50.0, 15.0, 1.5, 2.0]),
            (SectionFamily::PlainC, &[150.0, 50.0, 1.5, 2.0]),
            (SectionFamily::LippedZ, &[200.0, 60.0, 18.0, 2.0, 3.0]),
            (SectionFamily::Omega, &[40.0, 30.0, 20.0, 0.8, 1.0]),
        ];
        for (family, values) in ok {
            assert_eq!(check(family, values), Ok(()), "{family:?}");
        }
        // A zero radius is a sharp corner, never a floor violation.
        assert_eq!(
            check(SectionFamily::IShape, &[300.0, 150.0, 7.0, 10.0, 0.0]),
            Ok(())
        );
    }

    #[test]
    fn stage_order_is_finite_then_caps_then_floor() {
        let i = SectionFamily::IShape;
        assert_eq!(
            check(i, &[f64::NAN, 2e6, 0.0, 10.0, 15.0]),
            Err((ErrorCode::NonFiniteNumber, "h_mm"))
        );
        assert_eq!(
            check(i, &[300.0, 2e6, 0.0, 10.0, 15.0]),
            Err((ErrorCode::LimitExceeded, "b_mm"))
        );
        assert_eq!(
            check(i, &[300.0, 150.0, 0.0, 10.0, 15.0]),
            Err((ErrorCode::InvalidArgument, "tw_mm"))
        );
        assert_eq!(
            check(i, &[300.0, 150.0, 7.0, 10.0, -1.0]),
            Err((ErrorCode::InvalidArgument, "r_mm"))
        );
        assert_eq!(
            check(i, &[300.0, 150.0, 7.0, 10.0, 0.0005]),
            Err((ErrorCode::InvalidArgument, "r_mm"))
        );
    }

    #[test]
    fn family_consistency_rules_name_the_parameter() {
        let cases: [(SectionFamily, &[f64], &str); 12] = [
            (
                SectionFamily::IShape,
                &[20.0, 150.0, 7.0, 10.0, 0.0],
                "tf_mm",
            ),
            (
                SectionFamily::IShape,
                &[300.0, 150.0, 150.0, 10.0, 0.0],
                "tw_mm",
            ),
            (
                SectionFamily::IShape,
                &[300.0, 150.0, 7.0, 10.0, 72.0],
                "r_mm",
            ),
            (
                SectionFamily::Channel,
                &[100.0, 50.0, 6.0, 10.0, 45.0],
                "r_mm",
            ),
            (SectionFamily::Angle, &[100.0, 8.0, 8.0, 0.0], "t_mm"),
            (SectionFamily::Angle, &[100.0, 80.0, 8.0, 73.0], "r_mm"),
            (SectionFamily::Rhs, &[100.0, 100.0, 50.0, 0.0], "t_mm"),
            (SectionFamily::Rhs, &[100.0, 100.0, 5.0, 51.0], "r_mm"),
            (SectionFamily::Chs, &[100.0, 50.0], "t_mm"),
            (
                SectionFamily::LippedC,
                &[150.0, 50.0, 3.0, 1.5, 2.0],
                "c_mm",
            ),
            (
                SectionFamily::LippedC,
                &[150.0, 50.0, 80.0, 1.5, 2.0],
                "c_mm",
            ),
            (SectionFamily::Omega, &[40.0, 3.0, 20.0, 0.8, 1.0], "r_mm"),
        ];
        for (family, values, field) in cases {
            assert_eq!(
                check(family, values),
                Err((ErrorCode::InvalidArgument, field)),
                "{family:?} {values:?}"
            );
        }
    }

    #[test]
    fn simplified_section_drops_only_the_radius() {
        let s = ParametricSection::new(SectionFamily::Rhs, vec![200.0, 100.0, 6.0, 12.0]);
        let simple = s.map(|s| s.without_radius());
        assert_eq!(
            simple.as_ref().map(ParametricSection::values),
            Ok(&[200.0, 100.0, 6.0, 0.0][..])
        );
        let chs = ParametricSection::new(SectionFamily::Chs, vec![168.0, 5.0]);
        assert_eq!(chs.clone().map(|c| c.without_radius()), chs);
    }

    #[test]
    fn custom_sections_are_capped_but_never_repaired() {
        let square = vec![[0.0, 0.0], [100.0, 0.0], [100.0, 100.0], [0.0, 100.0]];
        let ok = CustomSection {
            outer: square.clone(),
            cavities: vec![vec![[10.0, 10.0], [10.0, 20.0], [20.0, 20.0]]],
        };
        assert_eq!(ok.validate(), Ok(()));
        let code = |c: CustomSection| c.validate().map_err(|e| e.code);
        assert_eq!(
            code(CustomSection {
                outer: square[..2].to_vec(),
                cavities: vec![],
            }),
            Err(ErrorCode::InvalidArgument)
        );
        assert_eq!(
            code(CustomSection {
                outer: vec![[f64::INFINITY, 0.0], [1.0, 0.0], [0.0, 1.0]],
                cavities: vec![],
            }),
            Err(ErrorCode::NonFiniteNumber)
        );
        assert_eq!(
            code(CustomSection {
                outer: vec![[2e9, 0.0], [1.0, 0.0], [0.0, 1.0]],
                cavities: vec![],
            }),
            Err(ErrorCode::LimitExceeded)
        );
        assert_eq!(
            code(CustomSection {
                outer: square.clone(),
                cavities: vec![square.clone(); 257],
            }),
            Err(ErrorCode::LimitExceeded)
        );
        assert_eq!(
            code(CustomSection {
                outer: vec![[0.0, 0.0]; 1025],
                cavities: vec![],
            }),
            Err(ErrorCode::LimitExceeded)
        );
    }
}
